using System;using System.IO;using System.Reflection;using System.Collections.Generic;using System.Net;using System.Web.Script.Serialization;
class NativeNetworkCheck {static int Main(string[] args){try{var asm=Assembly.LoadFrom(args[0]);var t=asm.GetType("OreumMok.Bridge",true);object bridge=Activator.CreateInstance(t,new object[]{true});t.GetField("RemoteUrl").SetValue(bridge,"https://oreummok-cloud.onrender.com");var status=(Dictionary<string,object>)t.GetMethod("Call").Invoke(bridge,new object[]{"status",null});((IDisposable)bridge).Dispose();if(!(bool)status["initialized"])throw new Exception("Cloud not initialized");var request=(HttpWebRequest)WebRequest.Create("https://oreummok-cloud.onrender.com/healthz");t.GetMethod("ConfigureRequest").Invoke(null,new object[]{request});request.Timeout=120000;request.AllowAutoRedirect=false;Dictionary<string,object> health;var json=new JavaScriptSerializer();using(var response=request.GetResponse())using(var r=new StreamReader(response.GetResponseStream()))health=json.Deserialize<Dictionary<string,object>>(r.ReadToEnd());var ai=(Dictionary<string,object>)health["ai"];if(!ai.ContainsKey("fullChatRequestValidated")||!(bool)ai["fullChatRequestValidated"]||!(bool)ai["calculationCheck"])throw new Exception("Live AI probe not ready");File.WriteAllText(args[1],json.Serialize(new{nativeBridgeHttps=true,cloudVersion=status["version"],liveCalculationProbe=true,model=ai["model"]}));return 0;}catch(Exception e){File.WriteAllText(args[1],e.GetType().Name+": "+e.Message);return 1;}}}